  void formatsJson() {
    EcommerceItems ecommerceItems =
        EcommerceItems.builder()
            .item(
                EcommerceItem.builder()
                    .sku("XYZ12345")
                    .name("Matomo - The big book about web analytics")
                    .category("Education & Teaching")
                    .price(23.1)
                    .quantity(2)
                    .build())
            .item(
                EcommerceItem.builder()
                    .sku("B0C2WV3MRJ")
